def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    if n <= 4:
        return 'C'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    last_opp = opp[-1]
    total_opp_def = opp.count('D')
    total_my_def = my.count('D')

    if total_opp_def == 0:
        return 'C'

    if last_opp == 'C':
        return 'C'

    # Break DD cycle: if last 3 rounds are all DD
    if n >= 3:
        if my[-1] == 'D' and my[-2] == 'D' and my[-3] == 'D' and opp[-1] == 'D' and opp[-2] == 'D' and opp[-3] == 'D':
            return 'C'

    if n >= 2 and opp[-2] == 'D' and last_opp == 'D':
        return 'D'

    opp_rate = total_opp_def / n
    my_rate = total_my_def / n

    if opp_rate <= 0.15 and my_rate <= 0.2:
        return 'C'

    if opp_rate <= 0.35:
        return 'D' if rng.random() < 0.5 else 'C'

    if opp_rate < 0.6:
        return 'D'

    return 'D' if rng.random() < 0.85 else 'C'
